// Font table: Excalidraw font slots (integer ids) paired with Korean fonts.
//
// Adding slots: Excalidraw 0.18 looks up a text element's fontFamily (integer) in the FONT_FAMILY table and uses the key name as-is
// as the CSS font name (getFontFamilyString). So adding a key to the table and registering a font face of the same name
// creates a new slot. Keys are added when this module is imported (before Excalidraw first draws). The faces (400+ FontFace entries,
// extra-faces.js, generated by scripts/fetch-kfonts.py) are registered by ensureExtraFaces on first need, so the entry CSS does not grow
// (when the font popup opens, or when text of that slot enters the scene).
//
// ids 20-39 are reserved for Cera. When upgrading Excalidraw, always check whether FONT_FAMILY and FONT_FAMILY_FALLBACKS
// use these numbers (if they overlap, registerFontFamilies throws). Never change a number once used
// because text in already-saved boards carries that number.
import { FONT_FAMILY, CaptureUpdateAction } from "@excalidraw/excalidraw";

import { EXTRA, registerFontFamilies } from "./slots.js";
import { tr } from "../../i18n.js";

registerFontFamilies(FONT_FAMILY);

