// Register the added slots' font faces only once (lazy chunk). The canvas, editor and PNG use them exactly like the CSS @font-face.
const EXTRA_IDS = new Set(Object.values(EXTRA));
const EXTRA_CSS = new Set(Object.keys(EXTRA));
let facesReady = null;
export function ensureExtraFaces() {
  if (typeof document === "undefined" || !document.fonts || typeof FontFace === "undefined") return Promise.resolve(false);
  if (!facesReady) {
    facesReady = import("./extra-faces.js").then(({ default: list }) => {
      for (const [family, weight, file, unicodeRange] of list) {
        document.fonts.add(new FontFace(family, `url(/kfonts/${file}) format("woff2")`, { weight: String(weight), style: "normal", display: "swap", unicodeRange }));
      }
      return true;
    }).catch((err) => { facesReady = null; console.warn("글꼴 목록을 못 불러왔어요", err); return false; });   // try again next time
  }
  return facesReady;
}

// Preload that font: loading must start the moment it is chosen so the first character is measured with that font's width.
export async function preloadFont(font, text = "가나다 abc 123") {
  if (!font?.family || typeof document === "undefined" || !document.fonts) return [];
  if (EXTRA_CSS.has(font.css)) await ensureExtraFaces();
  return document.fonts.load(`16px "${font.css}"`, text).catch(() => []);
}

// Line spacing and alignment buttons
export const LINE_HEIGHTS = [[1.15, tr("좁게", "Tight")], [1.25, tr("보통", "Normal")], [1.6, tr("넓게", "Loose")]];
export const ALIGNS = [["left", tr("왼쪽", "Left")], ["center", tr("가운데", "Center")], ["right", tr("오른쪽", "Right")]];

// Load the font pieces of received text directly, and redraw the text if anything was newly loaded.
// Why: in WebKit (Safari), document.fonts.check returns true even for pieces not yet loaded and never fires 'loadingdone',
// so Excalidraw's font loading and redraw are skipped, leaving text written by others in a fallback font
// (verified 2026-11-20). We call load without going through check, and when it finishes we swap in new objects with the same version
// to clear only the render cache (WeakMap). Since the version is unchanged, nothing is re-sent to the server.
// For text in an added slot, register the faces first (lazy injection). Characters whose load failed (rejected) are requested again next time.
// When redrawing, only text in the loaded fonts is replaced with new objects.
const asked = new Map();   // CSS font name -> characters already requested
const cssName = (id) => Object.keys(FONT_FAMILY).find((k) => FONT_FAMILY[k] === id);
export function loadTextFonts(api, elements) {
  if (!api || typeof document === "undefined" || !document.fonts) return;
  const want = new Map();
  let extra = false;
  for (const e of elements) {
    if (e.type !== "text" || e.isDeleted || !e.text) continue;
    const css = cssName(e.fontFamily); if (!css) continue;
    const seen = asked.get(css) || new Set(); asked.set(css, seen);
    for (const ch of e.text) if (ch.trim() && !seen.has(ch)) { seen.add(ch); want.set(css, (want.get(css) || "") + ch); }
    if (EXTRA_IDS.has(e.fontFamily) && want.has(css)) extra = true;
  }
  if (!want.size) return;
  (extra ? ensureExtraFaces() : Promise.resolve()).then(() => Promise.all([...want].map(([css, chars]) =>
    document.fonts.load(`16px "${css}"`, chars).then(() => css, () => {
      const seen = asked.get(css); for (const ch of chars) seen.delete(ch);   // failed: request again in the next batch
      return null;
    })))).then((done) => {
    const ids = new Set(done.filter(Boolean).map((css) => FONT_FAMILY[css]));
    if (!ids.size) return;
    api.updateScene({ elements: api.getSceneElementsIncludingDeleted().map((e) => (e.type === "text" && ids.has(e.fontFamily) ? { ...e } : e)), captureUpdate: CaptureUpdateAction.NEVER });
  });
}

// Before export (PNG, copy, share), load the fonts of all text in the scene.
// Why: the new slots' (21-24) font faces are registered only on use, and only the pieces for used characters are loaded. The export canvas may
// not wait for loading to finish, so characters not fully loaded get baked in with a fallback font. Unlike loadTextFonts, this does not use the 'already requested' table;
// it reloads every character in the scene (already loaded pieces finish immediately). WebKit's check() returns a false true,
// so we do not filter with check.
// - The whole thing, including lazy face registration (ensureExtraFaces), is awaited within the timeout.
// - If face registration fails, those slots are failed. If load rejects, or returns an empty array and no face of that name exists at all, it is failed.
// - document.fonts.ready (whole document) is not awaited, so slow loads elsewhere do not make already loaded fonts look failed.
// - On timeout, only fonts that have not finished are returned as failed.
const hasFace = (css) => { for (const f of document.fonts) if (f.family.replace(/^["']|["']$/g, "") === css) return true; return false; };
export async function ensureSceneFonts(elements, { timeout = 8000 } = {}) {
  if (typeof document === "undefined" || !document.fonts) return { families: [], failed: [] };
  const want = new Map();
  let extra = false;
  for (const e of elements) {
    if (e.type !== "text" || e.isDeleted || !e.text) continue;
    const css = cssName(e.fontFamily); if (!css) continue;
    if (EXTRA_IDS.has(e.fontFamily)) extra = true;
    const set = want.get(css) || new Set(); want.set(css, set);
    for (const ch of e.text) if (ch.trim()) set.add(ch);
  }
  if (!want.size) return { families: [], failed: [] };
  const settled = new Set(), failed = new Set();
  const work = (async () => {
    if (extra && !(await ensureExtraFaces())) for (const css of want.keys()) if (EXTRA_CSS.has(css)) { failed.add(css); settled.add(css); }
    await Promise.all([...want].filter(([css]) => !settled.has(css)).map(([css, set]) =>
      document.fonts.load(`16px "${css}"`, [...set].join("")).then(
        (faces) => { if (!(faces && faces.length) && !hasFace(css)) failed.add(css); settled.add(css); },
        () => { failed.add(css); settled.add(css); })));
  })();
  let timer;
  await Promise.race([work, new Promise((res) => { timer = setTimeout(res, timeout); })]);
  clearTimeout(timer);
  for (const css of want.keys()) if (!settled.has(css)) failed.add(css);
  return { families: [...want.keys()], failed: [...failed] };
}
